# Owner-private forensic export of latest P2 block, sanitized to fixed enums.
# No network, provider POST, P2 replay, file/claim deletion or Owner restart.
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$spool = Join-Path $env:ProgramData 'TorrentTVVietsub\LaptopHostOps'
$request = Get-Content -LiteralPath (Join-Path $spool 'Requests\request.json') -Raw | ConvertFrom-Json
if ($request.schema -cne 'TTV-LAPTOP-HOSTOPS-REQUEST-V1' -or
    [string]$request.nonce -cnotmatch '^[0-9a-f]{32}$') {
    throw 'OWNER_P2_BLOCK_TRACE_REQUEST_INVALID'
}
$owner = Join-Path $env:LOCALAPPDATA 'TorrentTVVietsub\OwnerBridge'
$code = @'
from pathlib import Path
import json, re, sys, time, ast, hashlib
root=Path(sys.argv[1])
out=dict(schema='TTV-OWNER-P2-BLOCK-TRACE-V1',scope='NOT_OBSERVED',
         p3='NOT_OBSERVED',route='NOT_OBSERVED',claimed='NO',
         blocked='NO',reason='NOT_OBSERVED',exception_type='NOT_OBSERVED',
         exception_code='NOT_OBSERVED',fault_site='NOT_OBSERVED',
         provider_claim='NO',cache='NO',p4='NOT_OBSERVED')
def finish(): print(json.dumps(out,separators=(',',':'),ensure_ascii=True))
try:
    hf=root/'agent-health.json'; log=root/'diagnostics'/'owner-full.log'
    if any(p.is_symlink() or not p.is_file() for p in (hf,log)):
        out['scope']='LOG_UNAVAILABLE'; finish(); sys.exit(0)
    health=json.loads(hf.read_text('utf-8'))
    age=time.time()-health.get('observed_utc_epoch',0)
    if health.get('schema')!='TTV-OWNER-AGENT-HEALTH-V1' or health.get('state')!='READY' or not 0<=age<=30 or type(health.get('pid')) is not int:
        out['scope']='HEALTH_STALE'; finish(); sys.exit(0)
    with log.open('rb') as f:
        size=f.seek(0,2); start=max(0,size-524288)
        f.seek(start); body=f.read(524288)
    if start: body=body.partition(b'\n')[2]
    lines=body.decode('utf-8','replace').splitlines()
    marks=[(i,int(m.group(1))) for i,line in enumerate(lines)
           if (m:=re.fullmatch(r'OWNER_FULL_DIAGNOSTICS_STARTED pid=(\d{1,10}) epoch=\d{1,12}',line))]
    if not marks or marks[-1][1]!=health['pid']:
        out['scope']='SESSION_NOT_IN_TAIL'; finish(); sys.exit(0)
    session=lines[marks[-1][0]+1:]
    dispatch=[i for i,line in enumerate(session) if "OWNER_FULL_TRACE 'P3_SELECTION_ACCEPTED'" in line and "'status': 'DISPATCH'" in line]
    if not dispatch:
        out['scope']='NO_DISPATCH'; finish(); sys.exit(0)
    out['scope']='CURRENT_OWNER_SESSION'; out['p3']='DISPATCHED'
    current=session[dispatch[-1]+1:]
    allowed_routes={'VI_READY','EN_TRANSLATE','REVIEW_REQUIRED','NO_MATCH'}
    p4_codes=set(["NOT_OBSERVED","REVISION_READY","P4_ACTIVATE_HTTP_200","P4_ACTIVATE_REJECTED_P4_ACTIVATE_AUTH_INVALID","P4_ACTIVATE_REJECTED_P4_ACTIVATE_HTTP_200","P4_ACTIVATE_REJECTED_P4_ACTIVATE_REJECTED_","P4_ACTIVATE_REJECTED_P4_ACTIVATE_REPLAY","P4_ACTIVATE_REJECTED_P4_ACTIVATE_SCHEMA_INVALID","P4_ACTIVATE_REJECTED_P4_ACTIVATION_REQUEST_INVALID","P4_ACTIVATE_REJECTED_P4_ASSUMED_SOURCE_MAP_INVALID","P4_ACTIVATE_REJECTED_P4_ASSUMED_SOURCE_MISSING","P4_ACTIVATE_REJECTED_P4_DERIVATION_SCOPE_INVALID","P4_ACTIVATE_REJECTED_P4_DEVICE_SECRET_INVALID","P4_ACTIVATE_REJECTED_P4_EVENT_CALLBACK_INVALID","P4_ACTIVATE_REJECTED_P4_HTTPS_TLS_CONTEXT_REQUIRED","P4_ACTIVATE_REJECTED_P4_MOCK_FACTORY_MEDIA_MISMATCH","P4_ACTIVATE_REJECTED_P4_MOCK_ONE_MEDIA_ONLY","P4_ACTIVATE_REJECTED_P4_MOCK_SOURCE_FACTORY_SCOPE_INVALID","P4_ACTIVATE_REJECTED_P4_PAIRED_PORT_INVALID","P4_ACTIVATE_REJECTED_P4_PROGRESSIVE_FACTORY_SCOPE_INVALID","P4_ACTIVATE_REJECTED_P4_PROGRESSIVE_FEED_BIND_FAILED","P4_ACTIVATE_REJECTED_P4_PROGRESSIVE_SOURCE_MISMATCH","P4_ACTIVATE_REJECTED_P4_READY_FACTORY_MEDIA_MISMATCH","P4_ACTIVATE_REJECTED_P4_READY_FEED_PUBLISH_FAILED","P4_ACTIVATE_REJECTED_P4_REVISION_CURRENT_SOURCE_HOLD","P4_ACTIVATE_REJECTED_P4_REVISION_HTTP_200","P4_ACTIVATE_REJECTED_P4_REVISION_HTTP_204","P4_ACTIVATE_REJECTED_P4_ROLLING_ABANDONED_JOB_HOLD","P4_ACTIVATE_REJECTED_P4_ROLLING_CHECKPOINT_GAP","P4_ACTIVATE_REJECTED_P4_ROLLING_CHECKPOINT_HASH_CHANGED","P4_ACTIVATE_REJECTED_P4_ROLLING_CHECKPOINT_INVALID","P4_ACTIVATE_REJECTED_P4_ROLLING_CHECKPOINT_NOT_VERIFIED","P4_ACTIVATE_REJECTED_P4_ROLLING_CURRENT_TV_UNAVAILABLE","P4_ACTIVATE_REJECTED_P4_ROLLING_REVISION_IDENTITY_INVALID","P4_ACTIVATE_REJECTED_P4_ROLLING_SELECTED_MEDIA_CHANGED","P4_ACTIVATE_REJECTED_P4_ROLLING_SOURCE_CHANGED","P4_ACTIVATE_REJECTED_P4_ROLLING_SOURCE_INDEX_INVALID","P4_ACTIVATE_REJECTED_P4_ROLLING_SOURCE_NOT_VERIFIED","P4_ACTIVATE_REJECTED_P4_ROLLING_SOURCE_RECEIPT_INVALID","P4_ACTIVATE_REJECTED_P4_ROLLING_TORRSERVER_FILE_CHANGED","P4_ACTIVATE_REJECTED_P4_ROLLING_TV_SESSION_CHANGED","P4_ACTIVATE_REJECTED_P4_SOURCE_FACTORY_INVALID","P4_ACTIVATE_REJECTED_P4_SOURCE_FACTORY_MEDIA_MISMATCH","P4_ACTIVATE_REJECTED_P4_TOO_MANY_SESSIONS","P4_ACTIVATE_REJECTED_P4_TOO_MANY_SOURCES","P4_ACTIVATE_REJECTED_P4_TRANSLATION_START_FAILED","P4_ACTIVATE_REJECTED_P4_VARIANT_FACTORY_SCOPE_INVALID","P4_ACTIVATE_REJECTED_P4_VARIANT_SOURCE_MISMATCH","P4_ACTIVATE_REJECTED_P4_VARIANT_UNSUPPORTED","P4_ACTIVATE_REJECTED_P4_VERIFIED_VI_FACTORY_SCOPE_INVALID","P4_ACTIVATE_REJECTED_UNCLASSIFIED","P4_ACTIVATE_REJECTED_OTHER","P4_REVISION_CURRENT_SOURCE_HOLD"])
    for line in current:
        m=re.fullmatch(r"OWNER_FULL_TRACE 'P4_DELIVERY_STATUS' \{'code': '([A-Z0-9_]+)'\}",line)
        if m: out['p4']=m.group(1) if m.group(1) in p4_codes else 'P4_ACTIVATE_REJECTED_OTHER'
        if line.startswith('AUTO_SOURCE_ROUTE='):
            v=line.partition('=')[2]
            if v in allowed_routes: out['route']=v
        if "OWNER_FULL_TRACE 'P2_EVENT_CLAIMED'" in line: out['claimed']='YES'
        if line=='AUTO_PROVIDER_DOWNLOAD=ATTEMPTED_ONCE': out['provider_claim']='YES'
        if line=='AUTO_SUBTITLE_CACHED=YES': out['cache']='YES'
        if 'P4_REVISION_HTTP_200' in line: out['p4']='REVISION_READY'
    blocks=[i for i,line in enumerate(current) if "OWNER_FULL_TRACE 'P2_EVENT_BLOCKED'" in line]
    if not blocks:
        finish(); sys.exit(0)
    out['blocked']='YES'
    after=current[blocks[-1]+1:blocks[-1]+101]
    known={'NO_APPROVED_DOWNLOAD','CANDIDATE_BINDING_MISMATCH',
           'BAD_DOWNLOAD_SCHEMA','BAD_SUBTITLE_TIMELINE','EMPTY_SUBTITLE',
           'INVALID_SUBTITLE_SIZE_OR_FORMAT','SUBTITLE_NOT_UTF8',
           'UNSAFE_SUBTITLE_TEXT','UNSAFE_CACHE_ROOT','CACHE_COLLISION',
           'BAD_API_JSON','RESPONSE_TOO_LARGE','RATE_LIMITED_429',
           'API_AUTH_DENIED','API_NETWORK_ERROR','UNTRUSTED_URL',
           'CROSS_HOST_AUTH_REDIRECT','MEDIA_BINDING_MISMATCH',
           'EN_DOWNLOAD_ALREADY_ATTEMPTED','MANUAL_DOWNLOAD_ALREADY_ATTEMPTED',
           'API_DOWNLOAD_INVALID_FILE_ID_406','API_DOWNLOAD_QUOTA_406',
           'API_DOWNLOAD_REJECTED_406',
           'AUTO_SOURCE_CACHE_INDEX_INVALID','AUTO_SOURCE_CACHE_DIGEST_MISMATCH',
           'BAD_CONTENT_DIGEST','BAD_CUE_COUNT'}
    known.update(["AGY_ACCOUNT_REQUIRED_ADC_MODE_REFUSED","AGY_ACCOUNT_REQUIRED_API_KEY_MODE_REFUSED","AGY_ACCOUNT_SETTINGS_INVALID","AGY_ACCOUNT_SETTINGS_UNREADABLE","AGY_ADC_AUTH","AGY_APP_ACCOUNT_SETTINGS_INVALID","AGY_APP_ACCOUNT_SETTINGS_UNREADABLE","AGY_CLI_NOT_INSTALLED_FOR_OWNER","AGY_EN_NO_MATCH","AGY_EVENT_INVALID","AGY_LIVE_PROVIDER_FORBIDDEN_IN_CI","AGY_MODEL_SLUG_INVALID","AGY_MODEL_THINKING_LEVEL_MISMATCH","AGY_MULTIPLE_RESULTS","AGY_NO_SUCCESSFUL_RESULT","AGY_OWNER_HOME_UNAVAILABLE","AGY_OWNER_PREFLIGHT_UNAVAILABLE","AGY_PERSONAL_ACCOUNT_MODE_REQUIRED","AGY_PROCESS_FAILED_RESULT_UNKNOWN","AGY_PROCESS_START_FAILED","AGY_RESPONSE_TOO_LARGE","AGY_STRUCTURED_OUTPUT_REQUIRED","AGY_TIMEOUT_RESULT_UNKNOWN","AGY_TRANSLATION_COUNT_INVALID","AGY_TRANSLATION_ENVELOPE_INVALID","AGY_TRANSLATION_ID_OR_TEXT_INVALID","AGY_TRANSLATION_TEXT_EMPTY","AGY_TRANSLATION_TEXT_MARKUP_UNSUPPORTED","AGY_TRANSLATION_TEXT_NUL","AGY_TRANSLATION_TEXT_TOO_LONG","AGY_TRANSLATION_TEXT_UTF8_INVALID","AGY_UNEXPECTED_TOOL_USAGE","AUTO_AGY_EN_INCOMPLETE_TRANSLATION","AUTO_AGY_EN_SOURCE_INVALID","AUTO_AGY_SOURCE_ACQUIRER_INVALID","AUTO_CACHED_VI_FINAL_INVALID","AUTO_DUAL_VERIFIED_MEDIA_REQUIRED","AUTO_LEAN120_ABANDONED_JOB_HOLD","AUTO_LEAN120_ABSOLUTE_PRIVATE_STATE_REQUIRED","AUTO_LEAN120_AUTHORIZED_EN_HANDOFF_REQUIRED","AUTO_LEAN120_CHECKPOINT_DIGEST_MISMATCH","AUTO_LEAN120_CHECKPOINT_INVALID","AUTO_LEAN120_FINAL_FILE_COLLISION","AUTO_LEAN120_FINAL_TIMELINE_INVALID","AUTO_LEAN120_FIRST_WINDOW_CUE_LIMIT_INVALID","AUTO_LEAN120_INCOMPLETE","AUTO_LEAN120_JOB_KEY_INVALID","AUTO_LEAN120_PILOT_WINDOW_LIMIT_INVALID","AUTO_LEAN120_PRIOR_PROVIDER_INFLIGHT_HOLD","AUTO_LEAN120_PROVIDER_NOT_ENABLED","AUTO_LEAN120_RUNNER_INVALID","AUTO_LEAN120_SOURCE_CHANGED","AUTO_LEAN120_UNCERTAIN_BATCH_MANUAL_RECONCILE","AUTO_LEAN120_WINDOW_PLAN_UNCERTAIN","AUTO_LEAN120_WINDOW_PLAN_UNVERIFIED","AUTO_LOCAL_EN_INCOMPLETE_TRANSLATION","AUTO_PROVIDER_SEARCH_DISABLED","AUTO_SOURCE_CACHE_DIGEST_MISMATCH","AUTO_SOURCE_CACHE_FILENAME_INVALID","AUTO_SOURCE_CACHE_FILE_MISSING","AUTO_SOURCE_CACHE_FILE_UNREADABLE","AUTO_SOURCE_CACHE_INDEX_CONFLICT","AUTO_SOURCE_CACHE_INDEX_INVALID","AUTO_TORRENT_EMBEDDED_READER_INVALID","AUTO_TORRENT_EN_INCOMPLETE_TRANSLATION","AUTO_TORRENT_SIDECAR_READER_INVALID","AUTO_V3_LOCAL_SOURCE_IDENTITY_MISMATCH","AUTO_V3_LOCAL_SOURCE_REQUIRES_MEDIA","AUTO_V3_SOURCE_FINGERPRINT_MISMATCH","AUTO_V3_VERIFIED_MEDIA_REQUIRED","AUTO_VIETSUB_BAD_SOURCE_LANGUAGE","AUTO_VIETSUB_INCOMPLETE_TRANSLATION","AUTO_VIETSUB_INVALID_CONFIGURATION","AUTO_VIETSUB_INVALID_MEDIA_NAME","AUTO_VIETSUB_LIVE_PROVIDER_FORBIDDEN_IN_CI","AUTO_VIETSUB_OWNER_SETTING_DISABLED","AUTO_VIETSUB_PERMISSIONS_NOT_ENABLED","AUTO_VIETSUB_PRIVATE_ROOT_REQUIRED","AUTO_VIETSUB_PROVIDER_NOT_ENABLED","AUTO_VIETSUB_SOURCE_FINGERPRINT_INVALID","AUTO_VIETSUB_TRANSLATION_NOT_ENABLED","BRAIN_EN_CACHE_CONFLICT","BRAIN_EN_DESTINATION_UNTRUSTED","BRAIN_EN_FINGERPRINT_INVALID","BRAIN_EN_INBOX_SYMLINK","BRAIN_EN_INPUT_FILE_INVALID","BRAIN_EN_INPUT_UNREADABLE","BRAIN_EN_NOT_STAGED","BRAIN_EN_PRIVATE_ROOT_INVALID","BRAIN_EN_RECEIPT_INVALID","BRAIN_EN_RELEASE_MISMATCH","BRAIN_EN_SOURCE_METADATA_INVALID","BRAIN_EN_SRT_CHANGED","BRAIN_EN_SRT_QA_FAILED","BRAIN_EN_SRT_SIZE_INVALID","BRAIN_EN_STAGE_CONFLICT","BRAIN_EN_STAGE_UNTRUSTED","BRAIN_EN_VERIFIED_MEDIA_REQUIRED","BRAIN_EN_VIDEO_NAME_INVALID","LEAN120_GLOSSARY_INVALID","LEAN120_WINDOW_INVALID","OWNER_BRIDGE_AGENT_LOCK_OPEN_FAILED","OWNER_BRIDGE_AGENT_LOCK_SYMLINK","OWNER_BRIDGE_ALREADY_RUNNING","OWNER_BRIDGE_BACKGROUND_SELECTION_INVALID","OWNER_BRIDGE_BAD_POLL_INTERVAL","OWNER_BRIDGE_BAD_PROCESSOR","OWNER_BRIDGE_BAD_VIDEO_NAME","OWNER_BRIDGE_DIAGNOSTIC_CALLBACK_INVALID","OWNER_BRIDGE_EVENT_","OWNER_BRIDGE_EVENT_BAD_SCHEMA","OWNER_BRIDGE_EVENT_BLOCKED_NO_RETRY","OWNER_BRIDGE_EVENT_CORRUPT","OWNER_BRIDGE_EVENT_INVALID","OWNER_BRIDGE_EVENT_PREPROVIDER_DEFERRED","OWNER_BRIDGE_EVENT_PREPROVIDER_DEFER_HOLD","OWNER_BRIDGE_EVENT_REJECTED","OWNER_BRIDGE_EVENT_REJECTED_SYMLINK","OWNER_BRIDGE_EVENT_TOO_LARGE","OWNER_BRIDGE_EVENT_UNTRUSTED","OWNER_BRIDGE_HEALTH_STATE_INVALID","OWNER_BRIDGE_HEALTH_SYMLINK","OWNER_BRIDGE_INVALID_RESULT","OWNER_BRIDGE_NO_OWNER_RUNTIME_IN_CI","OWNER_BRIDGE_PREPROVIDER_REASON_INVALID","OWNER_BRIDGE_PRIVATE_INBOX_SYMLINK","OWNER_BRIDGE_PRIVATE_ROOT_INVALID","OWNER_BRIDGE_RETRY_STATE_INVALID","OWNER_BRIDGE_SOURCE_FINGERPRINT_INVALID","OWNER_BRIDGE_STARTED","OWNER_BRIDGE_STARTUP_BLOCKED_PRIVATE_REVIEW","OWNER_BRIDGE_TRUSTED_V3_FACTORY_INVALID","OWNER_BRIDGE_TRUSTED_V3_PROCESSOR_INVALID","OWNER_BRIDGE_V3_SESSION_INVALID","P4_ACTIVATE_AUTH_INVALID","P4_ACTIVATE_HTTP_200","P4_ACTIVATE_REJECTED_","P4_ACTIVATE_REPLAY","P4_ACTIVATE_SCHEMA_INVALID","P4_ACTIVATION_REQUEST_INVALID","P4_ASSUMED_SOURCE_MAP_INVALID","P4_ASSUMED_SOURCE_MISSING","P4_DERIVATION_SCOPE_INVALID","P4_DEVICE_SECRET_INVALID","P4_EVENT_CALLBACK_INVALID","P4_HTTPS_TLS_CONTEXT_REQUIRED","P4_MOCK_FACTORY_MEDIA_MISMATCH","P4_MOCK_ONE_MEDIA_ONLY","P4_MOCK_SOURCE_FACTORY_SCOPE_INVALID","P4_PAIRED_PORT_INVALID","P4_PROGRESSIVE_FACTORY_SCOPE_INVALID","P4_PROGRESSIVE_FEED_BIND_FAILED","P4_PROGRESSIVE_SOURCE_MISMATCH","P4_READY_FACTORY_MEDIA_MISMATCH","P4_READY_FEED_PUBLISH_FAILED","P4_REVISION_CURRENT_SOURCE_HOLD","P4_REVISION_HTTP_200","P4_REVISION_HTTP_204","P4_ROLLING_ABANDONED_JOB_HOLD","P4_ROLLING_CHECKPOINT_GAP","P4_ROLLING_CHECKPOINT_HASH_CHANGED","P4_ROLLING_CHECKPOINT_INVALID","P4_ROLLING_CHECKPOINT_NOT_VERIFIED","P4_ROLLING_CURRENT_TV_UNAVAILABLE","P4_ROLLING_REVISION_IDENTITY_INVALID","P4_ROLLING_SELECTED_MEDIA_CHANGED","P4_ROLLING_SOURCE_CHANGED","P4_ROLLING_SOURCE_INDEX_INVALID","P4_ROLLING_SOURCE_NOT_VERIFIED","P4_ROLLING_SOURCE_RECEIPT_INVALID","P4_ROLLING_TORRSERVER_FILE_CHANGED","P4_ROLLING_TV_SESSION_CHANGED","P4_SOURCE_FACTORY_INVALID","P4_SOURCE_FACTORY_MEDIA_MISMATCH","P4_TOO_MANY_SESSIONS","P4_TOO_MANY_SOURCES","P4_TRANSLATION_START_FAILED","P4_VARIANT_FACTORY_SCOPE_INVALID","P4_VARIANT_SOURCE_MISMATCH","P4_VARIANT_UNSUPPORTED","P4_VERIFIED_VI_FACTORY_SCOPE_INVALID","RESOLVER_AMBIGUOUS_LOCAL_EN","RESOLVER_LOCAL_VIDEO_NAME_MISMATCH","RESOLVER_LOCAL_VIDEO_SIZE_MISMATCH","RESOLVER_NOT_ACTIVE_AUTHENTICATED_PLAY","RESOLVER_OWNER_MAPPING_INVALID","RESOLVER_OWNER_MAPPING_UNAVAILABLE","RESOLVER_OWNER_MEDIA_ROOT_INVALID","RESOLVER_OWNER_OR_VIEWER_GATE_BLOCKED","RESOLVER_PLAYBACK_READER_UNAVAILABLE","RESOLVER_SELECTED_MEDIA_MISMATCH","RESOLVER_SERVER_FILE_MISMATCH","RESOLVER_SERVER_PATH_INVALID","RESOLVER_SIDECAR_DIRECTORY_MISMATCH","RESOLVER_SIDECAR_NAME_MISMATCH","RESOLVER_SIDECAR_SYMLINK_REFUSED","RESOLVER_SOURCE_FINGERPRINT_MISMATCH","RESOLVER_TORRSERVER_READER_UNAVAILABLE","RESOLVER_TRUSTED_SNAPSHOT_REQUIRED","RESOLVER_TV_SESSION_MISMATCH","RESOLVER_UNTRUSTED_PRIVATE_PATH","V3_CURRENT_MEDIA_UNAVAILABLE","V3_CURRENT_SOURCE_MISMATCH","V3_EPISODE_METADATA_CONFLICT","V3_SERVER_READER_UNAVAILABLE","V3_SESSION_AND_FINGERPRINT_REQUIRED","V3_TV_READER_UNAVAILABLE","V3_TV_REFRESH_UNAVAILABLE","V3_TV_SELECTION_CHANGED"])
    # Recognize only literal exception codes in installed Python source; no dynamic text export.
    app=root/'app'
    modules={}
    for folder in (app/'poc/p2-sub-discovery', app/'poc/p2-aisub'):
        for file in folder.glob('*.py'):
            if file.is_symlink() or file.name.startswith('test_') or file.stat().st_size>1000000: continue
            try:
                tree=ast.parse(file.read_text('utf-8-sig'))
                modules[file.name]=file
                for node in ast.walk(tree):
                    if isinstance(node,ast.Constant) and isinstance(node.value,str) and re.fullmatch(r'[A-Z][A-Z0-9_]{3,90}',node.value):
                        known.add(node.value)
            except (OSError,UnicodeError,SyntaxError): continue
    sites={'download_selected','download_manual_vi','download_manual_en',
           '_request','_claim_one_post','validate_timed_text',
           'write_private_cache','_remember_source','selected_media',
           'run_claimed','_safe_https','_json','_milliseconds'}
    site='NOT_OBSERVED'; site_line=0
    for line in after:
        if "OWNER_FULL_TRACE 'P3_SELECTION_ACCEPTED'" in line: break
        m=re.search(r'File "[^"]*[/\\]([a-zA-Z0-9_]+\.py)", line (\d{1,5}), in ([a-zA-Z_][a-zA-Z0-9_]*)',line)
        if m and m.group(1) in modules:
            site=m.group(1).removesuffix('.py')+'_'+m.group(3)
            site=site[:65]; site_line=int(m.group(2))
        m=re.fullmatch(r'(?:[a-zA-Z_][a-zA-Z_0-9]*\.)?([A-Za-z]+Error):\s*([A-Z][A-Z0-9_]{3,100})',line.strip())
        if m:
            out['exception_type']=m.group(1) if m.group(1) in {'SubtitleApiError','ValueError','OSError','RuntimeError','FileNotFoundError','TimeoutError'} else 'OTHER'
            code=m.group(2)
            out['exception_code']=code if code in known or re.fullmatch(r'API_HTTP_[345]\d\d',code) else 'OTHER'
        if line.startswith('OWNER_BRIDGE_BLOCK_REASON='):
            code=line.partition('=')[2]
            out['reason']=code if code in known or code=='UNCLASSIFIED' else 'OTHER'
    out['fault_site']=site+'_'+str(site_line) if site_line else site
except Exception:
    out['scope']='LOCAL_READ_ERROR'
finish()
'@
$rows = @(& py -3 -I -B -c $code $owner 2>$null)
if ($LASTEXITCODE -ne 0 -or $rows.Count -ne 1) { throw 'OWNER_BLOCK_TRACE_PROBE_FAILED' }
$summary = [string]$rows[0] | ConvertFrom-Json
$fields = @('schema','scope','p3','route','claimed','blocked','reason',
            'exception_type','exception_code','fault_site','provider_claim','cache','p4')
if ($summary.schema -cne 'TTV-OWNER-P2-BLOCK-TRACE-V1' -or
    (@($summary.PSObject.Properties.Name | Sort-Object) -join ',') -cne
        (@($fields | Sort-Object) -join ',') -or
    $summary.scope -cnotin @('NOT_OBSERVED','LOG_UNAVAILABLE','HEALTH_STALE',
         'SESSION_NOT_IN_TAIL','NO_DISPATCH','CURRENT_OWNER_SESSION','LOCAL_READ_ERROR') -or
    $summary.p3 -cnotin @('NOT_OBSERVED','DISPATCHED') -or
    $summary.route -cnotin @('NOT_OBSERVED','VI_READY','EN_TRANSLATE','REVIEW_REQUIRED','NO_MATCH') -or
    $summary.claimed -cnotin @('YES','NO') -or
    $summary.blocked -cnotin @('YES','NO') -or
    $summary.provider_claim -cnotin @('YES','NO') -or
    $summary.cache -cnotin @('YES','NO') -or
    $summary.p4 -cnotin @('NOT_OBSERVED','REVISION_READY','P4_ACTIVATE_HTTP_200','P4_ACTIVATE_REJECTED_P4_ACTIVATE_AUTH_INVALID','P4_ACTIVATE_REJECTED_P4_ACTIVATE_HTTP_200','P4_ACTIVATE_REJECTED_P4_ACTIVATE_REJECTED_','P4_ACTIVATE_REJECTED_P4_ACTIVATE_REPLAY','P4_ACTIVATE_REJECTED_P4_ACTIVATE_SCHEMA_INVALID','P4_ACTIVATE_REJECTED_P4_ACTIVATION_REQUEST_INVALID','P4_ACTIVATE_REJECTED_P4_ASSUMED_SOURCE_MAP_INVALID','P4_ACTIVATE_REJECTED_P4_ASSUMED_SOURCE_MISSING','P4_ACTIVATE_REJECTED_P4_DERIVATION_SCOPE_INVALID','P4_ACTIVATE_REJECTED_P4_DEVICE_SECRET_INVALID','P4_ACTIVATE_REJECTED_P4_EVENT_CALLBACK_INVALID','P4_ACTIVATE_REJECTED_P4_HTTPS_TLS_CONTEXT_REQUIRED','P4_ACTIVATE_REJECTED_P4_MOCK_FACTORY_MEDIA_MISMATCH','P4_ACTIVATE_REJECTED_P4_MOCK_ONE_MEDIA_ONLY','P4_ACTIVATE_REJECTED_P4_MOCK_SOURCE_FACTORY_SCOPE_INVALID','P4_ACTIVATE_REJECTED_P4_PAIRED_PORT_INVALID','P4_ACTIVATE_REJECTED_P4_PROGRESSIVE_FACTORY_SCOPE_INVALID','P4_ACTIVATE_REJECTED_P4_PROGRESSIVE_FEED_BIND_FAILED','P4_ACTIVATE_REJECTED_P4_PROGRESSIVE_SOURCE_MISMATCH','P4_ACTIVATE_REJECTED_P4_READY_FACTORY_MEDIA_MISMATCH','P4_ACTIVATE_REJECTED_P4_READY_FEED_PUBLISH_FAILED','P4_ACTIVATE_REJECTED_P4_REVISION_CURRENT_SOURCE_HOLD','P4_ACTIVATE_REJECTED_P4_REVISION_HTTP_200','P4_ACTIVATE_REJECTED_P4_REVISION_HTTP_204','P4_ACTIVATE_REJECTED_P4_ROLLING_ABANDONED_JOB_HOLD','P4_ACTIVATE_REJECTED_P4_ROLLING_CHECKPOINT_GAP','P4_ACTIVATE_REJECTED_P4_ROLLING_CHECKPOINT_HASH_CHANGED','P4_ACTIVATE_REJECTED_P4_ROLLING_CHECKPOINT_INVALID','P4_ACTIVATE_REJECTED_P4_ROLLING_CHECKPOINT_NOT_VERIFIED','P4_ACTIVATE_REJECTED_P4_ROLLING_CURRENT_TV_UNAVAILABLE','P4_ACTIVATE_REJECTED_P4_ROLLING_REVISION_IDENTITY_INVALID','P4_ACTIVATE_REJECTED_P4_ROLLING_SELECTED_MEDIA_CHANGED','P4_ACTIVATE_REJECTED_P4_ROLLING_SOURCE_CHANGED','P4_ACTIVATE_REJECTED_P4_ROLLING_SOURCE_INDEX_INVALID','P4_ACTIVATE_REJECTED_P4_ROLLING_SOURCE_NOT_VERIFIED','P4_ACTIVATE_REJECTED_P4_ROLLING_SOURCE_RECEIPT_INVALID','P4_ACTIVATE_REJECTED_P4_ROLLING_TORRSERVER_FILE_CHANGED','P4_ACTIVATE_REJECTED_P4_ROLLING_TV_SESSION_CHANGED','P4_ACTIVATE_REJECTED_P4_SOURCE_FACTORY_INVALID','P4_ACTIVATE_REJECTED_P4_SOURCE_FACTORY_MEDIA_MISMATCH','P4_ACTIVATE_REJECTED_P4_TOO_MANY_SESSIONS','P4_ACTIVATE_REJECTED_P4_TOO_MANY_SOURCES','P4_ACTIVATE_REJECTED_P4_TRANSLATION_START_FAILED','P4_ACTIVATE_REJECTED_P4_VARIANT_FACTORY_SCOPE_INVALID','P4_ACTIVATE_REJECTED_P4_VARIANT_SOURCE_MISMATCH','P4_ACTIVATE_REJECTED_P4_VARIANT_UNSUPPORTED','P4_ACTIVATE_REJECTED_P4_VERIFIED_VI_FACTORY_SCOPE_INVALID','P4_ACTIVATE_REJECTED_UNCLASSIFIED','P4_ACTIVATE_REJECTED_OTHER','P4_REVISION_CURRENT_SOURCE_HOLD') -or
    $summary.exception_type -cnotmatch '^(NOT_OBSERVED|OTHER|SubtitleApiError|ValueError|OSError|RuntimeError|FileNotFoundError|TimeoutError)$' -or
    $summary.exception_code -cnotmatch '^[A-Z0-9_]{3,100}$' -or
    $summary.reason -cnotmatch '^[A-Z0-9_]{3,100}$' -or
    $summary.fault_site -cnotmatch '^[a-zA-Z0-9_]{3,80}$') {
    throw 'OWNER_BLOCK_TRACE_SUMMARY_INVALID'
}
$current = Get-Content -LiteralPath (Join-Path $spool 'Requests\request.json') -Raw | ConvertFrom-Json
if ($current.nonce -cne $request.nonce) { throw 'OWNER_BLOCK_TRACE_REQUEST_CHANGED' }
$summary | Add-Member -NotePropertyName nonce -NotePropertyValue $request.nonce
$payload = $summary | ConvertTo-Json -Compress
if ([Text.Encoding]::UTF8.GetByteCount($payload) -gt 1024) { throw 'OWNER_BLOCK_TRACE_OVERSIZE' }
$target = Join-Path $spool 'Receipts\block-trace.json'
$temp = $target + '.' + [Guid]::NewGuid().ToString('N') + '.tmp'
[IO.File]::WriteAllText($temp,$payload,[Text.UTF8Encoding]::new($false))
[IO.File]::Move($temp,$target,$true)
Write-Output 'OWNER_BLOCK_TRACE=SANITIZED_EXPORT_COMPLETE'
